# Reproducibly generated by window_make_lower_variant.py; c=0.0088 backup.
"""Exact numerical discovery of a global/minimizer cover for the NEW window.

The frozen old-window support library is never used. All new supports come
from window_interval_kernel.py. Positivity of its 16 convex-core certificates,
|k''|<=4 and |w''|<=8 are explicit analytic obligations, not Lean axioms.
Successful completion of this program is NOT an unconditional zeta theorem.
Every accepted value leaf uses integer mixture capacities and exact flow.
"""
from pathlib import Path
from fractions import Fraction as F
import argparse, functools, hashlib, importlib.util, json, math, os, sys, time
import numpy as np

HERE=Path(__file__).resolve().parent
ROOT=HERE.parent
sys.path.insert(0,str(HERE))
import window_interval_kernel as ik
spec=importlib.util.spec_from_file_location('w10_generate',ROOT/'research-20261016-w10-cert/generate.py')
g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
PARAM=ik.PARAM;P=ik.DATA
g.PAR=PARAM;g.P=P;g.BS=P['b_numerators'];g.TERMS=[tuple(t) for t in P['a_upper'] if t[2]]
g.SEP=123*g.SC//128;g.TARGET=11*(g.DEN//1250);g.OLD=False
SC=g.SC;STEP=64;DS=10**12;TMAX=1<<24
CORE=6881 # strictly inside 21/100 * SC
COEFF=np.array([float(x) for x in ik.COEFF])
FREQ=np.r_[np.sqrt(2)/(2*np.pi),np.arange(1,25)]
NORM=float((ik.Z.l+ik.Z.u)/2)

def kernel(xs):
    xs=np.asarray(xs)
    return (((np.sinc(xs[:,None]+FREQ)+np.sinc(xs[:,None]-FREQ))@COEFF)/(2*NORM))**2
g.kernel=kernel

def floor(x):return x.numerator//x.denominator
def ceil(x):return -floor(-x)

def root():
    cn=88000000
    extra=cn*SC-sum(g.BS)*g.SEP
    up=[g.SEP+ceil(F(extra,b)) for b in g.BS]
    lo=[(j-i)*g.SEP for i,j in g.ALL]
    hi=[sum(up[i:j]) for i,j in g.ALL]
    for z,(i,j) in enumerate(g.ALL):
        hi[z]=min(hi[z],(j-i)*g.SEP+ceil(F(extra,min(g.BS[i:j]))))
    cl=g.close(lo,hi)
    assert cl is not None and cl[:2]==(lo,hi)
    return lo,hi
g.root=root

@functools.lru_cache(None)
def support(p):
    """A quantized true tangent on a convex core, extended only below zero."""
    n=round(p/SC)
    assert 1<=n<=16 and n*SC-CORE<=p<=n*SC+CORE
    v,d=ik.w_jet(F(p,SC),1)
    lower,upper=n*SC-CORE,n*SC+CORE
    if d.u<=0 and v.u+d.u*F(upper-p,SC)<=0:upper=TMAX
    if d.l>=0 and v.u+d.l*F(lower-p,SC)<=0:lower=0
    vl=floor(v.l*10**10);dl=floor(d.l*10**9);du=ceil(d.u*10**9)
    assert vl>=0 and du>=dl
    return lower,upper,vl,dl,du-dl

def anchor(x,n,step=STEP):
    return min(n*SC+CORE,max(n*SC-CORE,round(x/step)*step))

@functools.lru_cache(200000)
def constant_lower(l,u):
    if u-l>=SC:return 0
    p=round((l+u)/(2*STEP))*STEP
    k,d=ik.kernel_jet(F(p,SC),1)
    radius=F(max(abs(l-p),abs(u-p)),SC)
    error=max(abs(d.l),abs(d.u))*radius+2*radius*radius
    kl,ku=k.l-error,k.u+error
    value=min(abs(kl),abs(ku))**2 if kl*ku>0 else F(0)
    return floor(value*10**10)

HINTS={}
@functools.lru_cache(200000)
def base_anchors(l,u):
    points=set()
    # A negative-slope tangent can extend to the right, and a positive-slope
    # tangent to the left. Cores far from both ends cannot be positive here.
    ns=set()
    for x in [l,u,(l+u)//2]:
        ns.update([math.floor(x/SC),math.ceil(x/SC)])
    for n in ns:
        if 1<=n<=16:
            for x in [l,u,(l+u)//2,n*SC-CORE,n*SC+CORE,n*SC]:
                points.add(anchor(x,n,512))
    return tuple(sorted(points))

def lines(l,u,base=None):
    ans=[(0,0,-2)]
    points=set(base_anchors(l,u));points.update(HINTS.get((l,u),()))
    for p in sorted(points):
        pl,pu,v,sl,err=support(p)
        if pl<=l and u<=pu:
            const=SC*v-10*sl*p-10*err*max(p-l,0)
            slope=10*sl
            if max(const+slope*l,const+slope*u)>0:ans.append((const,slope,p))
    lb=constant_lower(l,u)
    if lb:ans.append((SC*lb,0,-1))
    return ans
g.lines=lines

def certify(state,passes=3):
    best=None
    for _ in range(passes):
        rec=g.certify(state,export=True)
        if best is None or int(rec.get('floor_numerator','-1'))>int(best.get('floor_numerator','-1')):best=rec
        if int(rec.get('floor_numerator','-1'))>=g.TARGET or 'gaps' not in rec:break
        added=False
        for i,j,a in g.TERMS:
            z=g.LOOK[i,j];l,u=state[0][z],state[1][z]
            x=sum(rec['gaps'][i:j])*SC
            n=round(x/SC)
            if 1<=n<=16 and abs(x-n*SC)<=CORE:
                p=anchor(x,n)
                pts=HINTS.setdefault((l,u),set())
                if p not in pts:pts.add(p);added=True
        if not added:break
    return best

@functools.lru_cache(200000)
def derivative_range(l,u):
    n=round((l+u)/(2*SC))
    if 1<=n<=16 and n*SC-CORE<=l<=u<=n*SC+CORE:
        # Convexity gives monotonic w'. Round endpoints outwards within core.
        pl=max(n*SC-CORE,(l//STEP)*STEP)
        pu=min(n*SC+CORE,ceil(F(u,STEP))*STEP)
        dl=ik.w_jet(F(pl,SC),1)[1].l;du=ik.w_jet(F(pu,SC),1)[1].u
    elif u-l>=2*SC:dl,du=F(-7),F(7)
    else:
        p=round((l+u)/(2*STEP))*STEP
        d=ik.w_jet(F(p,SC),1)[1]
        error=8*F(max(abs(l-p),abs(u-p)),SC)
        dl=max(F(-7),d.l-error);du=min(F(7),d.u+error)
    return floor(dl*DS),ceil(du*DS)

def stationary_exclusion(state):
    low=[b*DS for b in g.BS];up=low.copy()
    for i,j,a in g.TERMS:
        z=g.LOOK[i,j];dl,du=derivative_range(state[0][z],state[1][z])
        for r in range(i,j):low[r]+=a*dl;up[r]+=a*du
    for r in range(9):
        if up[r]<0:return {'coordinate':r,'direction':1,'gradient_upper':str(up[r]),'gradient_denominator':str(g.D*DS)}
        if low[r]>0 and state[0][r]>g.SEP:
            return {'coordinate':r,'direction':-1,'gradient_lower':str(low[r]),'gradient_denominator':str(g.D*DS)}
    return None

USED_SUPPORTS=set()
original_support=support
def tracked_support(p):USED_SUPPORTS.add(p);return original_support(p)
support=tracked_support

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--max-nodes',type=int,default=1000)
    ap.add_argument('--output',type=Path,default=HERE/'window-lower-global-cover.json')
    ap.add_argument('--resume',type=Path)
    ap.add_argument('--no-stationary',action='store_true')
    args=ap.parse_args();start=time.monotonic()
    sources=[Path(__file__),Path(ik.__file__),PARAM,HERE/'window_interval_kernel.json']
    hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
    cv=json.loads((HERE/'window_interval_kernel.json').read_bytes())
    assert cv['all_positive'] and len(cv['regions'])>=16
    todo=[(root(),0,'r')];accepted=[];branches=[];checked=0;depthmax=0
    if args.resume:
        old=json.loads(args.resume.read_bytes())
        assert old['input_sha256']==hashes
        todo=[(x['state'],x['depth'],x['path']) for x in old['unresolved']]
        accepted=old['accepted'];branches=old['branches'];checked=old['checked'];depthmax=old['maxdepth']
    def save():
        assert hashes=={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
        out={'scope':__doc__,'input_sha256':hashes,'target':'11/1250','SC':SC,
             'denominator':str(g.DEN),'separation':'123/128','pid':os.getpid(),
             'root':root(),'checked':checked,'maxdepth':depthmax,'accepted_count':len(accepted),
             'stationary_count':sum(x['kind']=='stationary' for x in accepted),
             'unresolved_count':len(todo),'seconds':time.monotonic()-start,
             'analytic_obligations':['all sixteen convex-core bounds','actual |k second derivative| <= 4',
                 'actual |w second derivative| <= 8','coercive global minimizer and KKT transfer'],
             'analytic_obligations_Lean_proven':False,'global_floor_Lean_proven':False,
             'new_zero_proportion_proven':False,'accepted':accepted,'branches':branches,
             'unresolved':[{'state':s,'depth':d,'path':p} for s,d,p in todo],
             'tangent_data':[[p,*original_support(p)] for p in sorted(USED_SUPPORTS)]}
        temp=args.output.with_suffix('.partial');temp.write_text(json.dumps(out,separators=(',',':'))+'\n',encoding='utf8');temp.replace(args.output)
        return out
    initial=checked
    while todo and checked-initial<args.max_nodes:
        state,depth,path=todo.pop();checked+=1;depthmax=max(depthmax,depth)
        if state[1][8]<state[0][0]:
            accepted.append({'path':path,'depth':depth,'kind':'reflection'});continue
        rec=certify(state)
        if int(rec.get('floor_numerator','-1'))>=g.TARGET:
            accepted.append({'path':path,'depth':depth,'kind':'value','result':rec})
        else:
            excl=None if args.no_stationary else stationary_exclusion(state)
            if excl:accepted.append({'path':path,'depth':depth,'kind':'stationary','result':excl})
            else:
                ax,q=g.cut(state,rec)
                assert state[0][ax]<q<state[1][ax]
                left=g.split(state,ax,q,True);right=g.split(state,ax,q,False)
                branches.append({'path':path,'axis':ax,'cut':q})
                if right is not None:todo.append((right,depth+1,path+'1'))
                if left is not None:todo.append((left,depth+1,path+'0'))
        if checked%250==0:
            print(json.dumps({'checked':checked,'accepted':len(accepted),'pending':len(todo),'maxdepth':depthmax,
                'seconds':time.monotonic()-start,'last_floor':rec.get('floor'),'jet_cache':ik.kernel_jet.cache_info().currsize}),flush=True)
        if checked%1000==0:save()
    out=save()
    print(json.dumps({k:out[k] for k in ['checked','accepted_count','stationary_count','unresolved_count','maxdepth','seconds']}),flush=True)

if __name__=='__main__':main()
